package com.pedro.racasclasses.race.impl;
import com.pedro.racasclasses.RacasClasses;import com.pedro.racasclasses.race.Race;import java.util.*;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.phys.Vec3;import net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent;
public class GiffRace implements Race {private static final Map<UUID,Long> ABILITY_COOLDOWNS=new HashMap<>();private static final ResourceLocation KNOCKBACK_ID=ResourceLocation.fromNamespaceAndPath(RacasClasses.MODID,"giff_knockback_resistance");@Override public String getId(){return "giff";}@Override public String getDisplayName(){return "Giff";}@Override public double getMaxHealth(){return 26;}@Override public double getAttackDamage(){return 1.1;}@Override public double getMovementSpeed(){return .09;}@Override public double getScale(){return 1.2;}@Override public double getArmor(){return 2;}
 @Override public void onRangedDamage(ServerPlayer p,LivingIncomingDamageEvent e){if(p.getMainHandItem().is(net.minecraft.world.item.Items.CROSSBOW))e.setAmount(e.getAmount()*1.2f);}@Override public void onPlayerJoin(ServerPlayer p){AttributeInstance a=p.getAttribute(Attributes.KNOCKBACK_RESISTANCE);if(a!=null&&a.getModifier(KNOCKBACK_ID)==null)a.addPermanentModifier(new AttributeModifier(KNOCKBACK_ID,.5,AttributeModifier.Operation.ADD_VALUE));}
 @Override public boolean canUseAbility(){return true;}@Override public void executeAbility(ServerPlayer p){long t=p.serverLevel().getServer().getTickCount();Long r=ABILITY_COOLDOWNS.get(p.getUUID());if(r!=null&&t<r){p.sendSystemMessage(Component.literal("§cHeadbutt em recarga: §f"+(r-t)/20.0+"s"));return;}for(LivingEntity target:p.level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(3),e->e!=p)){target.hurt(p.damageSources().playerAttack(p),5);Vec3 push=target.position().subtract(p.position()).normalize();target.push(push.x*1.5,.5,push.z*1.5);}ABILITY_COOLDOWNS.put(p.getUUID(),t+400);p.sendSystemMessage(Component.literal("§aHeadbutt!"));}}
